<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Favorites — GasGo</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="topbar"><div class="container nav"><a class="brand" href="../index.php">⛽ GasGo</a><a href="../index.php">Home</a></div></header><main class="section"><div class="container"><h1>Your Favorites</h1><p class="muted">Favorites are saved only in this browser using localStorage.</p><div id="favorites"></div></div></main><script src="assets/js/app.js"></script><script>
fetch('api/stations.php').then(r=>r.json()).then(data=>{const ids=JSON.parse(localStorage.getItem('gasgo_favorites')||'[]');const box=document.querySelector('#favorites');const chosen=data.filter(s=>ids.includes(Number(s.id)));box.innerHTML=chosen.length?'<div class="station-grid">'+chosen.map(s=>`<article class="card"><h3>${s.name}</h3><p>${s.barangay} — ${s.address}</p><a class="btn btn-primary" href="station.php?id=${s.id}">View details</a></article>`).join('')+'</div>':'<p>No favorite stations yet.</p>'}).catch(()=>document.querySelector('#favorites').innerHTML='<p>Unable to load stations.</p>');
</script></body></html>